<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}
require_once __DIR__.'/../config/config.php';
$stmt=$pdo->prepare("SELECT ci.quantity,b.*,COALESCE(p.company_name,s.shop_name,NULLIF(u.display_name,''),u.email,'ผู้ขายวนวรรณ') seller_name FROM cart_items ci JOIN books b ON b.book_id=ci.book_id LEFT JOIN publishers p ON b.seller_type='publisher' AND p.publisher_id=b.seller_id LEFT JOIN shops s ON b.seller_type='shop' AND s.shop_id=b.seller_id LEFT JOIN users u ON b.seller_type='user' AND u.user_id=b.seller_id WHERE ci.user_id=? ORDER BY b.seller_type,b.seller_id,ci.created_at DESC");
$stmt->execute([(int)$_SESSION['user_id']]);$items=$stmt->fetchAll(PDO::FETCH_ASSOC);$groups=[];
foreach($items as $item){$key=$item['seller_type'].'-'.$item['seller_id'];$groups[$key]['key']=$key;$groups[$key]['type']=$item['seller_type'];$groups[$key]['id']=(int)$item['seller_id'];$groups[$key]['name']=wanawanSellerName($item['seller_name'],$item['seller_type']);$groups[$key]['items'][]=$item;}
// เช็คสถานะ wishlist ของสินค้าในตะกร้า
$wishlistedIds=[];
if($items){$wIds=array_column($items,'book_id');$wMarks=implode(',',array_fill(0,count($wIds),'?'));$wStmt=$pdo->prepare("SELECT book_id FROM wishlists WHERE user_id=? AND book_id IN ($wMarks)");$wStmt->execute(array_merge([(int)$_SESSION['user_id']],$wIds));$wishlistedIds=array_flip($wStmt->fetchAll(PDO::FETCH_COLUMN));}
function cartImg(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return$v;$v=ltrim(str_replace('\\','/',$v),'/');return str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/books/'.$v;}
?>
