rt-btn:hover svg{transform:scale(1.15)}.cart-btn-wish{background:#fdf0f4;border:1.5px solid #f0c4d4;color:#d4708a}.cart-btn-wish:hover{background:#f8dce7;border-color:#d4708a;box-shadow:0 3px 12px rgba(212,112,138,.3)}.cart-btn-wish svg{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.cart-btn-wish--active{background:#fff5f0;border-color:#f0c4c4;color:#e8546a;box-shadow:0 2px 10px rgba(232,84,106,.25)}.cart-btn-wish--active svg{fill:#e8546a;stroke:#e8546a;color:#e8546a}.cart-btn-wish--active:hover{background:#fde8ec;border-color:#e8a0b0;box-shadow:0 3px 14px rgba(232,84,106,.35)}.cart-btn-delete{background:#fef0f0;border:1.5px solid #f5c6c6;color:#d94f4f}.cart-btn-delete:hover{background:#c0392b;border-color:#c0392b;color:#fff;box-shadow:0 3px 12px rgba(201,57,43,.35)}.cart-btn-delete svg{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.cart-btn[data-tooltip]{position:relative}.cart-btn[data-tooltip]::after{content:attr(data-tooltip);position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%) translateY(4px);background:#3a3a3a;color:#fff;padding:4px 10px;border-radius:6px;font-size:11px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s}.cart-btn[data-tooltip]:hover::after{opacity:1;transform:translateX(-50%) translateY(0)}.price{color:var(--secondary-color);font-weight:700;text-align:right}.qty{display:flex;align-items:center;border:1px solid #d7d3ce;border-radius:20px;overflow:hidden;background:#fff;width:max-content;margin-top:12px}.qty button,.qty span{height:30px;display:flex;justify-content:center;align-items:center;border:none;background:transparent;color:var(--text-dark)}.qty button{width:30px;font-size:18px;cursor:pointer}.qty span{width:34px;font-size:14px;font-weight:600;border-left:1px solid #eee;border-right:1px solid #eee}.qty button:disabled{opacity:.35;cursor:not-allowed}.stock-warn{display:inline-block;padding:3px 9px;border-radius:5px;font-size:12px;font-weight:600;margin:4px 4px 4px 0}.stock-low{background:#fff0f0;color:#c0392b;border:1px solid #f5c6cb}.stock-soldout{background:#fde8e8;color:#a33;border:1px solid #e8b4b4}.stock-ok{background:#f5f5f5;color:#888;border:1px solid #e0e0e0}.stock-over{background:#fff8e1;color:#e67e22;border:1px solid #f5deb3}.summary{position:sticky;top:20px;height:max-content;padding:24px;border:1px solid #d8e1dc;border-radius:16px;background:#fff}.summary h2{margin:0 0 18px;color:var(--secondary-color)}.seller-breakdown{border-bottom:1px solid #eee;padding-bottom:12px;margin-bottom:12px}.seller-sum{padding:9px 0}.seller-sum strong{display:block;font-size:13px}.seller-sum div,.sum-row{display:flex;justify-content:space-between;gap:12px;color:var(--text-muted);font-size:13px;margin-top:4px}.sum-row{font-size:15px;margin:15px 0}.sum-total{border-top:1px solid #ddd;padding-top:17px;color:var(--secondary-color);font-size:21px;font-weight:700}.checkout{width:100%;height:54px;border:0;border-radius:10px;background:var(--secondary-color);color:#fff;font:inherit;font-weight:700;margin-top:14px;cursor:pointer}.checkout:disabled{background:#c8cbc8;cursor:not-allowed}.empty{text-align:center;padding:100px;color:var(--text-muted)}@media(max-width:1024px){.wrap{padding:30px 20px 60px}.layout{grid-template-columns:minmax(0,1fr) 260px;gap:16px}.summary{padding:16px}.summary h2{font-size:20px;margin-bottom:14px}.sum-row{font-size:13px;margin:10px 0}.sum-total{font-size:17px;padding-top:14px}.checkout{font-size:14px;height:48px}}@media(max-width:768px){.wrap{padding:12px;padding-bottom:180px}.title{font-size:20px;margin:0 0 15px}.layout{grid-template-columns:1fr;gap:0}.summary{position:fixed;bottom:0;left:0;right:0;top:auto;margin:0;border-radius:20px 20px 0 0;box-shadow:0 -5px 25px rgba(0,0,0,0.08);padding:15px;z-index:99}.seller-breakdown{display:none}.summary h2{display:none}.sum-row{margin:6px 0;font-size:12px}.sum-total{margin:8px 0 0;padding-top:10px;font-size:15px}.checkout{height:44px;margin-top:12px;font-size:14px}.item{grid-template-columns:22px 76px 1fr;padding:15px 12px;gap:12px;align-items:start}.cart-select{grid-column:1;grid-row:1/span 2;align-self:center;margin:0}.cover{grid-column:2;grid-row:1/span 2;width:76px;height:106px;border-radius:6px}.item > div:nth-of-type(2){grid-column:3;grid-row:1;display:flex;flex-direction:column;gap:3px}.item h3{font-size:14px;margin:0;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.item p{font-size:11px;margin:0}.stock-warn{font-size:10px;padding:2px 6px;width:max-content;margin:2px 0}.cart-action-row{margin-top:4px}.cart-btn{width:28px;height:28px;min-width:28px;min-height:28px;max-width:28px;max-height:28px;padding:0;}.cart-btn svg{width:14px;height:14px}.item > div:last-child{grid-column:3;grid-row:2;display:flex;align-items:flex-end;justify-content:space-between;border:none;padding:0;margin-top:4px}.price{text-align:left;font-size:15px;margin-bottom:2px}.qty{margin-top:0}.qty button,.qty span{height:26px;font-size:12px}.qty button{width:26px;min-width:26px;min-height:26px;max-width:26px;max-height:26px;padding:0;}.qty span{width:28px}.group-head{padding:12px;gap:10px}.store-icon{width:28px;height:28px;border-radius:6px}.store-icon svg{width:16px;height:16px}.store-name{font-size:14px}.group-total{display:none}.select-all-bar{padding:12px;margin-bottom:12px;border-radius:10px;font-size:14px}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><h1 class="title">ตะกร้าสินค้า</h1><?php if(!$items):?><div class="empty">ตะกร้าของคุณยังว่างอยู่</div><?php else:?><label class="select-all-bar"><input id="select-all" type="checkbox"><strong>เลือกสินค้าทั้งหมด</strong><span style="margin-left:auto;color:var(--text-muted)"><?=count($items)?> รายการ</span></label><div class="layout"><div><?php foreach($groups as $group):?><section class="group" data-seller="<?=htmlspecialchars($group['key'])?>"><header class="group-head"><input class="group-select" type="checkbox" aria-label="เลือกสินค้าทั้งหมดของ <?=htmlspecialchars($group['name'])?>"><span class="store-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 10v9h16v-9M3 10l2-5h14l2 5M3 10c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2M9 19v-4h6v4"/></svg></span><a class="store-name" href="/pages/partner_detail.php?type=<?=urlencode($group['type'])?>&amp;id=<?=$group['id']?>"><?=htmlspecialchars($group['name'])?> ›</a><span class="group-total" data-group-total>ยังไม่ได้เลือกสินค้า</span></header><?php foreach($group['items'] as $item): $stock=(int)$item['stock_quantity']; $itemOutOfStock=$stock<=0; $overStock=$item['quantity']>$stock; ?><article class="item <?=$itemOutOfStock?'item--soldout':''?>"><input class="cart-select" type="checkbox" data-book-id="<?=$item['book_id']?>" data-seller="<?=htmlspecialchars($group['key'])?>" data-seller-name="<?=htmlspecialchars($group['name'])?>" data-price="<?=$item['price']?>" data-quantity="<?=$item['quantity']?>" <?=$itemOutOfStock?'disabled':''?> aria-label="เลือก <?=htmlspecialchars($item['title'])?>"><div class="cover"><?php if($img=cartImg($item['image_cover'])):?><img src="<?=htmlspecialchars($img)?>" alt=""><?php endif;?></div><div><h3><?=htmlspecialchars($item['title'])?></h3><p>โดย <?=htmlspecialchars($item['author']?:'-')?></p><?php if($itemOutOfStock):?><span class="stock-warn stock-soldout">สินค้าหมดแล้ว</span><?php elseif($stock<10):?><span class="stock-warn stock-low">เหลือ <?=$stock?> เล่ม</span><?php else:?><span class="stock-warn stock-ok">คลัง <?=number_format($stock)?> เล่ม</span><?php endif;?><?php if($overStock&&!$itemOutOfStock):?><span class="stock-warn stock-over">⚠ จำนวนเกินสต็อก กรุณาลดจำนวน</span><?php endif;?><div class="cart-action-row"><button class="cart-btn cart-btn-wish <?=isset($wishlistedIds[$item['book_id']])?'cart-btn-wish--active':''?>" data-tooltip="<?=isset($wishlistedIds[$item['book_id']])?'นำออกจากรายการโปรด':'เพิ่มในรายการโปรด'?>" onclick="event.stopPropagation();toggleCartWishlist(<?=$item['book_id']?>,this)" aria-label="รายการโปรด"><svg viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg></button><button class="cart-btn cart-btn-delete" data-tooltip="ลบออกจากตะกร้า" onclick="event.stopPropagation();removeCart(<?=$item['book_id']?>)" aria-label="ลบออกจากตะกร้า"><svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg></button></div></div><div><div class="price">฿<?=number_format($item['price'],2)?></div><div class="qty"><button onclick="updateCart(<?=$item['book_id']?>,<?=$item['quantity']-1?>)" <?=$item['quantity']<=1?'disabled':''?>>−</button><span><?=$item['quantity']?></span><button onclick="updateCart(<?=$item['book_id']?>,<?=$item['quantity']+1?>)" <?=$item['quantity']>=$stock?'disabled':''?>>+</button></div></div></article><?php endforeach;?></section><?php endforeach;?></div><aside class="summary"><h2>สรุปคำสั่งซื้อ</h2><div class="seller-breakdown" id="seller-breakdown"><span style="color:var(--text-muted);font-size:13px">เลือกรายการเพื่อดูยอดแยกร้าน</span></div><div class="sum-row"><span>ยอดรวมสินค้า (<b id="selected-count">0</b> เล่ม)</span><span id="selected-subtotal">฿0.00</span></div><div class="sum-row"><span>ค่าจัดส่ง (<b id="selected-shops">0</b> ร้าน)</span><span id="selected-shipping">฿0.00</span></div><div class="sum-row"><span>ส่วนลดสมาชิก</span><span id="selected-discount">− ฿0.00</span></div><div class="sum-row sum-total"><span>ยอดรวมทั้งหมด</span><span id="selected-total">฿0.00</span></div><button class="checkout" id="checkout-button" disabled>กรุณาเลือกรายการสินค้า</button></aside></div><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?>
<script>
async function toggleCartWishlist(bookId, btn) {
    btn.disabled = true;
    try {
        const res = await fetch('/pages/handlers/wishlist_handler.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'toggle', book_id: bookId, source: 'book' })
        });
        const data = await res.json();
        if (!res.ok || !data.success) throw new Error(data.message || 'เกิดข้อผิดพลาด');
        if (data.active) {
            btn.classList.add('cart-btn-wish--active');
            btn.dataset.tooltip = 'นำออกจากรายการโปรด';
        } else {
            btn.classList.remove('cart-btn-wish--active');
            btn.dataset.tooltip = 'เพิ่มในรายการโปรด';
        }
    } catch (e) {
        alert(e.message);
    }
    btn.disabled = false;
}
document.addEventListener('DOMContentLoaded',()=>{const boxes=[...document.querySelectorAll('.cart-select')],all=document.getElementById('select-all'),money=v=>'฿'+v.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}),shippingFor=qty=>qty>0?45:0,checkout=document.getElementById('checkout-button');function sync(){document.querySelectorAll('.group').forEach(group=>{const own=[...group.querySelectorAll('.cart-select')],checked=own.filter(b=>b.checked);const control=group.querySelector('.group-select');control.checked=checked.length===own.length;control.indeterminate=checked.length>0&&checked.length<own.length});const checked=boxes.filter(b=>b.checked);all.checked=checked.length===boxes.length;all.indeterminate=checked.length>0&&checked.length<boxes.length;calculate()}function calculate(){let count=0,subtotal=0;const sellers={};boxes.forEach(b=>{if(!b.checked)return;const qty=Number(b.dataset.quantity)||0,line=(Number(b.dataset.price)||0)*qty;count+=qty;subtotal+=line;const key=b.dataset.seller;sellers[key]??={name:b.dataset.sellerName,subtotal:0,count:0};sellers[key].subtotal+=line;sellers[key].count+=qty});const shopCount=Object.keys(sellers).length,shipping=Object.values(sellers).reduce((sum,s)=>sum+shippingFor(s.count),0),discount=subtotal*.05,total=subtotal+shipping-discount;document.getElementById('selected-count').textContent=count;document.getElementById('selected-shops').textContent=shopCount;document.getElementById('selected-subtotal').textContent=money(subtotal);document.getElementById('selected-shipping').textContent=money(shipping);document.getElementById('selected-discount').textContent='− '+money(discount);document.getElementById('selected-total').textContent=money(total);document.getElementById('seller-breakdown').innerHTML=shopCount?Object.values(sellers).map(s=>{const fee=shippingFor(s.count);return`<div class="seller-sum"><strong>${escapeHtml(s.name)}</strong><div><span>${s.count} เล่ม · ค่าส่ง ${money(fee)}</span><span>${money(s.subtotal+fee-s.subtotal*.05)}</span></div></div>`}).join(''):'<span style="color:var(--text-muted);font-size:13px">เลือกรายการเพื่อดูยอดแยกร้าน</span>';document.querySelectorAll('.group').forEach(g=>{const chosen=[...g.querySelectorAll('.cart-select:checked')],amount=chosen.reduce((n,b)=>n+Number(b.dataset.price)*Number(b.dataset.quantity),0),qty=chosen.reduce((n,b)=>n+Number(b.dataset.quantity),0);g.querySelector('[data-group-total]').textContent=chosen.length?`เลือก ${qty} เล่ม · ค่าส่ง ${money(shippingFor(qty))}`:'ยังไม่ได้เลือกสินค้า'});checkout.disabled=!count;checkout.textContent=count?`สั่งซื้อ ${count} เล่ม จาก ${shopCount} ร้าน →`:'กรุณาเลือกรายการสินค้า'}function escapeHtml(v){const d=document.createElement('div');d.textContent=v;return d.innerHTML}all?.addEventListener('change',()=>{boxes.forEach(b=>{if(!b.disabled)b.checked=all.checked});sync()});document.querySelectorAll('.group-select').forEach(c=>c.addEventListener('change',()=>{c.closest('.group').querySelectorAll('.cart-select').forEach(b=>{if(!b.disabled)b.checked=c.checked});sync()}));boxes.forEach(b=>b.addEventListener('change',sync));sync()});
</script></body></html>
